package com.vandorlabs.neoforge.screen;
import com.google.gson.*;
import com.vandorlabs.screen.*;
/** The portable placement policy is compared against actual legacy ItemBlock callbacks. */
public final class ScreenPlacementChecks {
 public static void main(String[] args)throws Exception{JsonObject source;try(var reader=java.nio.file.Files.newBufferedReader(java.nio.file.Path.of(System.getProperty("screenPlacementReference")))){source=JsonParser.parseReader(reader).getAsJsonObject();}int cases=0;int[] horizontal={3,4,2,5};for(var row:source.getAsJsonArray("cases")){var expected=row.getAsJsonObject();var family=ScreenFamily.fromId(expected.get("id").getAsString());int support=expected.get("support").getAsInt(),slab=support==1||support==3?1:support==2||support==4?0:-1;float hit=.1F+.4F*expected.get("fraction").getAsInt();var actual=ScreenPlacement.place(family,expected.get("face").getAsInt(),horizontal[expected.get("yaw").getAsInt()],expected.get("sneak").getAsBoolean(),hit,hit,1-hit,support==5?family.decode(expected.get("supportMeta").getAsInt()).facing:-1,slab);if(family.encode(actual.state)!=expected.get("meta").getAsInt()||actual.wallPosition!=expected.get("wall").getAsInt()||actual.ceilingMounted!=expected.get("ceiling").getAsBoolean()||actual.ceilingPosition!=expected.get("ceilingPosition").getAsInt())throw new AssertionError("Native placement differs "+expected);cases++;}if(cases!=15120||!source.get("sha256").getAsString().equals("cd0ab9533bfab20698da64c977ede6b306d67b535d0b9873c99bb67670c98b5a"))throw new AssertionError("Source placement coverage changed");System.out.println("Native Screen placement PASS actual Source callbacks/item bridges="+cases);}
}
